START TRANSACTION;
ALTER TABLE furniture_inventory_instances ADD COLUMN IF NOT EXISTS instance_code CHAR(6) CHARACTER SET ascii COLLATE ascii_bin NULL AFTER id;
CREATE UNIQUE INDEX IF NOT EXISTS uq_furniture_inventory_instance_code ON furniture_inventory_instances(instance_code);
CREATE TABLE IF NOT EXISTS home_furniture_draw_catalog_versions(
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
 version_code VARCHAR(96) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 source_path VARCHAR(255) NOT NULL,
 source_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 rate_scale BIGINT UNSIGNED NOT NULL,
 active BOOLEAN NOT NULL DEFAULT FALSE,
 created_at DATETIME(3) NOT NULL DEFAULT UTC_TIMESTAMP(3),
 PRIMARY KEY(id),
 UNIQUE KEY uq_home_furniture_draw_catalog_version(version_code),
 UNIQUE KEY uq_home_furniture_draw_catalog_source(source_sha256)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS home_furniture_draw_grade_bands(
 catalog_version_id BIGINT UNSIGNED NOT NULL,
 grade_ordinal TINYINT UNSIGNED NOT NULL,
 grade_display_name VARCHAR(128) NOT NULL,
 weight_scaled BIGINT UNSIGNED NOT NULL,
 entry_count INT UNSIGNED NOT NULL,
 PRIMARY KEY(catalog_version_id,grade_ordinal),
 UNIQUE KEY uq_home_furniture_draw_grade_name(catalog_version_id,grade_display_name),
 CONSTRAINT fk_home_furniture_draw_grade_catalog FOREIGN KEY(catalog_version_id) REFERENCES home_furniture_draw_catalog_versions(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS home_furniture_draw_entries(
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
 catalog_version_id BIGINT UNSIGNED NOT NULL,
 source_sequence INT UNSIGNED NOT NULL,
 furniture_definition_id BIGINT UNSIGNED NOT NULL,
 grade_ordinal TINYINT UNSIGNED NOT NULL,
 within_grade_sequence INT UNSIGNED NOT NULL,
 source_display_snapshot VARCHAR(255) NOT NULL,
 source_rate_text VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 PRIMARY KEY(id),
 UNIQUE KEY uq_home_furniture_draw_entry_source(catalog_version_id,source_sequence),
 UNIQUE KEY uq_home_furniture_draw_entry_grade_sequence(catalog_version_id,grade_ordinal,within_grade_sequence),
 KEY idx_home_furniture_draw_entry_definition(furniture_definition_id),
 CONSTRAINT fk_home_furniture_draw_entry_catalog FOREIGN KEY(catalog_version_id) REFERENCES home_furniture_draw_catalog_versions(id) ON DELETE RESTRICT,
 CONSTRAINT fk_home_furniture_draw_entry_definition FOREIGN KEY(furniture_definition_id) REFERENCES furniture_definitions(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS home_furniture_draw_operations(
 operation_id BIGINT UNSIGNED NOT NULL,
 player_id BIGINT UNSIGNED NOT NULL,
 catalog_version_id BIGINT UNSIGNED NOT NULL,
 ticket_item_id BIGINT UNSIGNED NOT NULL,
 requested_quantity INT UNSIGNED NOT NULL,
 ticket_before BIGINT UNSIGNED NOT NULL,
 ticket_after BIGINT UNSIGNED NOT NULL,
 bag_count_before BIGINT UNSIGNED NOT NULL,
 bag_count_after BIGINT UNSIGNED NOT NULL,
 bag_capacity BIGINT UNSIGNED NOT NULL,
 seed_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 result_digest CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 created_at DATETIME(3) NOT NULL DEFAULT UTC_TIMESTAMP(3),
 PRIMARY KEY(operation_id),
 KEY idx_home_furniture_draw_operation_player(player_id,created_at),
 CONSTRAINT fk_home_furniture_draw_operation_operation FOREIGN KEY(operation_id) REFERENCES operations(id) ON DELETE RESTRICT,
 CONSTRAINT fk_home_furniture_draw_operation_player FOREIGN KEY(player_id) REFERENCES players(id) ON DELETE RESTRICT,
 CONSTRAINT fk_home_furniture_draw_operation_catalog FOREIGN KEY(catalog_version_id) REFERENCES home_furniture_draw_catalog_versions(id) ON DELETE RESTRICT,
 CONSTRAINT fk_home_furniture_draw_operation_ticket FOREIGN KEY(ticket_item_id) REFERENCES item_definitions(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS home_furniture_draw_results(
 operation_id BIGINT UNSIGNED NOT NULL,
 sequence_no INT UNSIGNED NOT NULL,
 catalog_entry_id BIGINT UNSIGNED NOT NULL,
 furniture_instance_id BIGINT UNSIGNED NOT NULL,
 grade_roll BIGINT UNSIGNED NOT NULL,
 item_roll BIGINT UNSIGNED NOT NULL,
 instance_code CHAR(6) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 PRIMARY KEY(operation_id,sequence_no),
 UNIQUE KEY uq_home_furniture_draw_result_instance(furniture_instance_id),
 UNIQUE KEY uq_home_furniture_draw_result_code(instance_code),
 CONSTRAINT fk_home_furniture_draw_result_operation FOREIGN KEY(operation_id) REFERENCES home_furniture_draw_operations(operation_id) ON DELETE RESTRICT,
 CONSTRAINT fk_home_furniture_draw_result_entry FOREIGN KEY(catalog_entry_id) REFERENCES home_furniture_draw_entries(id) ON DELETE RESTRICT,
 CONSTRAINT fk_home_furniture_draw_result_instance FOREIGN KEY(furniture_instance_id) REFERENCES furniture_inventory_instances(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
SET @home_furniture_draw_catalog_id=(SELECT id FROM home_furniture_draw_catalog_versions WHERE source_sha256='73c93af3f0a5d52e4539047a21ce0d08f33603275ca542974eb11f47f93b2195' LIMIT 1);
